bool leuInicio = int.TryParse(Console.ReadLine(), out int inicio);
bool leuFim = int.TryParse(Console.ReadLine(), out int fim);
if (!leuInicio && !leuFim)
{
    Console.WriteLine("Digite dois inteiros");
}
else if (inicio < 0 || fim < 0)
{
    Console.WriteLine("Contagem inválida");
}
else if (fim > inicio)
{
    Console.WriteLine("Conferir reposição");
}
else
{
    Console.WriteLine("Folhas usadas");
    Console.WriteLine(inicio - fim);
}

